private static int getRequiredApi(byte[] data) {
    if (!isRiffWebP(data)) return -1;
    // Iterate chunks starting at offset 12.
    int offset = 12;
    boolean alpha = false;
    boolean lossless = false;
    while (offset + 8 <= data.length) {
        String fourCC = new String(data, offset, 4, StandardCharsets.US_ASCII);
        int chunkSize = readIntLE(data, offset + 4);
        if (chunkSize < 0) break;
        if ("VP8 ".equals(fourCC)) {
            // lossy
        } else if ("VP8L".equals(fourCC)) {
            lossless = true;
        } else if ("VP8X".equals(fourCC)) {
            if (offset + 8 + 4 <= data.length) {
                int flags = readIntLE(data, offset + 8);
                alpha = (flags & 0x00000010) != 0;
            }
        }
